from json_kv import *
from ail import make_dir, open_binary, path_exists, remove_dir, remove_file, replace_path, write_bytes
def kv_read(path: str) -> str:
    file: binaryfile = open_binary(path, 'rb')
    try:
        data = file.read(8388609)
        if len(data) > 8388608:
            raise ValueError
        return data.decode('utf-8')
    finally:
        file.close()

def kv_commit(path: str, data: str) -> None:
    stage = path + '.ail-stage'
    make_dir(stage)
    try:
        write_bytes(stage + '/state.json', data.encode('utf-8'))
        replace_path(stage + '/state.json', path)
    finally:
        try:
            remove_file(stage + '/state.json')
        except OSError:
            pass
        remove_dir(stage)

def kv_process(path: str, data: str) -> str:
    values: dict[str, str] = {}
    if path_exists(path):
        values = kv_object(kv_read(path))
    kv_validate(values)
    store = KvStore(values)
    report = kv_batch(store, data)
    snapshot = kv_snapshot(store)
    if len(snapshot.encode()) > 8388608:
        raise ValueError
    kv_commit(path, snapshot)
    return report
